import { MapAnatomyFigure, SignedEigenlineFigure, DiagonalShiftFigure, ShiftedNullSpaceFigure, MatchedEigenpairsFigure, ObliqueCoordinatesFigure, IndependentDirectionsFigure, SymmetryDotFigure, QuadraticSpectrumFigure, RepeatedRootFigure, ComplexRotationFigure, ModePowersFigure, TransientCouplingFigure, StabilityRegionsFigure, DataCenteringFigure, CovarianceProductsFigure, RayleighWeightsFigure, PcaUnitsTiesFigure, IrisSpectrumFigure, ConservedModesFigure, GraphSignalModesFigure, SpringAnatomyFigure, UnequalMassFigure, JacobiPairFigure, JacobiBasisTraceFigure, EigenDiagnosticsFigure, NormalizedPowerFigure, ResidualGapFigure, SchurSensitivityFigure } from '../../components/lesson-labs/EigenvalueFigures.jsx';
import '../../components/lesson-labs/lesson-flow.css';
